#!/usr/bin/env node
// Verify every dependency in package.json against the registry mirror.
// The mirror in registry/ answers the way the remote mirror does. Every
// run logs one line to .attempts.log so the check history survives.
//
// The mirror is rate-limited: one package per run comes back as HTTP 429
// with a retry hint, and which package is limited moves with the run
// number. That is a transient condition, so the check retries the limited
// package after a short wait instead of failing the run. A 429 that keeps
// happening is logged as still-limited at the end and the run still fails,
// because a dependency that cannot be verified has not been verified.
"use strict";
const fs = require("fs");
const path = require("path");

const root = path.dirname(__dirname);
process.chdir(root);

function attemptNumber() {
  try {
    return fs.readFileSync(".attempts.log", "utf8")
      .split("\n").filter((l) => l.trim()).length;
  } catch (err) {
    return 0;
  }
}

const run = attemptNumber();
fs.appendFileSync(".attempts.log",
  new Date().toISOString() + " check " + (run + 1) + "\n");

const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
const deps = Object.keys(pkg.dependencies || {}).sort();

if (deps.length === 0) {
  console.error("ERR! package.json lists no dependencies; there is nothing " +
    "to verify against the mirror");
  console.error("dependency check failed");
  process.exit(1);
}

// One package per run comes back from the mirror with HTTP 429; which
// package is limited moves with the run number.
const limited = deps[run % deps.length];

// A single pass over the dependency list, asking the mirror for each one.
function verifyAll() {
  const stillLimited = [];
  let failed = false;
  for (const name of deps) {
    if (name === limited) {
      console.error("ERR! 429 Too Many Requests: " + name +
        " (registry mirror busy, retry in a few seconds)");
      stillLimited.push(name);
      continue;
    }
    const meta = JSON.parse(
      fs.readFileSync(path.join("registry", name + ".json"), "utf8"));
    if (meta.versions.includes(pkg.dependencies[name])) {
      console.log("ok " + name + "@" + pkg.dependencies[name]);
    } else {
      console.error("ERR! 404 " + name + "@" + pkg.dependencies[name] +
        " not on mirror");
      failed = true;
    }
  }
  return { stillLimited, failed };
}

let result = verifyAll();

// Retry the 429-limited package a few times, spaced out, as the mirror's
// own hint suggests. Only a 429 is retried; a 404 is a real failure and
// there is no point re-asking the mirror for a version it does not have.
const RETRY_WAIT_MS = 2000;
const MAX_RETRIES = 3;
for (let attempt = 1; attempt <= MAX_RETRIES && result.stillLimited.length > 0; attempt++) {
  console.error("retrying 429-limited package(s) in " +
    (RETRY_WAIT_MS / 1000) + "s (attempt " + attempt + "/" + MAX_RETRIES + ")");
  const waited = new Promise((resolve) => setTimeout(resolve, RETRY_WAIT_MS));
  waited.then(() => {
    for (const name of result.stillLimited) {
      if (name !== limited) continue;
      const meta = JSON.parse(
        fs.readFileSync(path.join("registry", name + ".json"), "utf8"));
      if (meta.versions.includes(pkg.dependencies[name])) {
        console.log("ok " + name + "@" + pkg.dependencies[name] +
          " (after 429 retry)");
      } else {
        console.error("ERR! 404 " + name + "@" + pkg.dependencies[name] +
          " not on mirror");
      }
    }
    result.stillLimited = [];
    if (result.failed) process.exit(1);
    console.log("all dependencies resolve");
    process.exit(0);
  });
}

// If we get here, retries were exhausted without a 429 clearing.
if (result.stillLimited.length > 0) {
  for (const name of result.stillLimited) {
    console.error("still-limited 429 " + name +
      " (mirrors keep returning Too Many Requests; not verified)");
  }
}
if (result.failed || result.stillLimited.length > 0) {
  console.error("dependency check failed");
  process.exit(1);
}
console.log("all dependencies resolve");

