// with a retry hint, and which package is limited moves with the run
// number. That is a transient condition, so the check asks the mirror
// again after a short wait, up to a bounded number of retries. Only a
// 429 is retried; a 404 is a real failure and the run stops there. A 429
// that survives all retries is reported as still-limited and the run
// still fails, because a dependency that cannot be verified has not been
// verified.
"use strict";
const fs = require("fs");
const path = require("path");

const root = path.dirname(__dirname);
process.chdir(root);

function attemptNumber() {
  try {
    return fs.readFileSync(".attempts.log", "utf8")
      .split("\n").filter((l) => l.trim()).length;
  } catch (err) {
    return 0;
  }
}

const run = attemptNumber();
fs.appendFileSync(".attempts.log",
  new Date().toISOString() + " check " + (run + 1) + "\n");

const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
const deps = Object.keys(pkg.dependencies || {}).sort();

if (deps.length === 0) {
  console.error("ERR! package.json lists no dependencies; there is nothing " +
    "to verify against the mirror");
  console.error("dependency check failed");
  process.exit(1);
}

// One package per run comes back from the mirror with HTTP 429; which
// package is limited moves with the run number.
const limited = deps[run % deps.length];

const RETRY_WAIT_MS = 2000;
const MAX_RETRIES = 3;

// Synchronous sleep so the retry loop can stay simple and readable.
function sleep(ms) {
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
}

let failed = false;
let stillLimited = false;
for (const name of deps) {
  if (name === limited) {
    console.error("ERR! 429 Too Many Requests: " + name +
      " (registry mirror busy, retry in a few seconds)");
  }
  let meta = null;
  for (let attempt = 0; ; attempt++) {
    if (name !== limited) {
      meta = JSON.parse(
        fs.readFileSync(path.join("registry", name + ".json"), "utf8"));
      break;
    }
    if (attempt >= MAX_RETRIES) {
      stillLimited = true;
      console.error("still-limited 429 " + name +
        " (mirrors keep returning Too Many Requests; not verified)");
      break;
    }
    console.error("retrying 429-limited package(s) in " +
      (RETRY_WAIT_MS / 1000) + "s (attempt " + (attempt + 1) + "/" +
      MAX_RETRIES + ")");
    sleep(RETRY_WAIT_MS);
  }
  if (meta !== null) {
    if (meta.versions.includes(pkg.dependencies[name])) {
      console.log("ok " + name + "@" + pkg.dependencies[name] +
        (name === limited ? " (after 429 retry)" : ""));
    } else {
      console.error("ERR! 404 " + name + "@" + pkg.dependencies[name] +
        " not on mirror");
      failed = true;
    }
  }
}
if (failed || stillLimited) {
  console.error("dependency check failed");
  process.exit(1);
}
console.log("all dependencies resolve");

